    sql << '              WHEN i.due_date >= (SELECT a.as_of FROM dash_demo.as_of a) - INTERVAL 90 DAY THEN 3\n'
    sql << '              ELSE 4 END AS ord,\n'
    sql << '         c.segment AS segment,\n'
    sql << '         i.amount + i.tax_amount AS owed\n'
    sql << '  FROM dash_demo.invoices i\n'
    sql << '  JOIN dash_demo.customers c ON c.customer_id = i.customer_id\n'
    sql << '  WHERE i.status IN (\'open\', \'overdue\', \'partially_paid\')\n'
    if (hasMinAmount) {
