    }
    if (hasAccountManagerId) {
        sql << '    AND c.account_manager_id = ?\n'
        params << asDeclaredType('accountManagerId', 'Integer', accountManagerId)
    } else {
        sql << '    AND 1=1\n'   // no value: this filter is off
    }
    sql << ')\n'
    sql << 'SELECT CASE ord WHEN 0 THEN \'Current\' WHEN 1 THEN \'1-30 days\' WHEN 2 THEN \'31-60 days\'\n'
    sql << '         WHEN 3 THEN \'61-90 days\' ELSE \'90+ days\' END AS bucket,\n'
    sql << '       round(sum(owed), 2) AS owed,\n'
