    sql << 'FROM aged\n'
    sql << 'GROUP BY ord\n'
    sql << 'ORDER BY ord\n'
    def data = params.isEmpty() ? dbSql.rows(sql.toString()) : dbSql.rows(sql.toString(), params)
    ctx.reportData('chart_dd14-chart-aging-buckets', data)
